import React, { useState } from 'react';

export default function StudentProfileSettings({ user }) {
  const [profile, setProfile] = useState({
    name: user?.name || "Student",
    phone: user?.phone || '',
    address: user?.address || '',
    password: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Profile changes saved successfully!");
  };

  return (
    <div style={styles.whiteBox}>
      <h2 style={{ marginTop: 0, fontSize: '20px', color: '#145c2e', fontWeight: 'bold' }}>
        ⚙️ Student Profile & Account Settings
      </h2>

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px', marginTop: '20px' }}>
        <div>
          <label style={styles.label}>Full Name:</label>
          <input 
            type="text" 
            value={profile.name} 
            onChange={e => setProfile({ ...profile, name: e.target.value })} 
            style={styles.inputLarge} 
          />
        </div>

        <div>
          <label style={styles.label}>Contact Phone Number:</label>
          <input 
            type="text" 
            value={profile.phone} 
            onChange={e => setProfile({ ...profile, phone: e.target.value })} 
            style={styles.inputLarge} 
          />
        </div>

        <div>
          <label style={styles.label}>Home Address:</label>
          <input 
            type="text" 
            value={profile.address} 
            onChange={e => setProfile({ ...profile, address: e.target.value })} 
            style={styles.inputLarge} 
          />
        </div>

        <div>
          <label style={styles.label}>Update Account Password:</label>
          <input 
            type="password" 
            placeholder="New Password" 
            value={profile.password} 
            onChange={e => setProfile({ ...profile, password: e.target.value })} 
            style={styles.inputLarge} 
          />
        </div>

        <button type="submit" style={styles.primaryBtn}>
          💾 Save Profile Changes
        </button>
      </form>
    </div>
  );
}

const styles = {
  whiteBox: { backgroundColor: '#fff', padding: '24px', borderRadius: '18px', border: '1px solid #e2e8f0', boxShadow: '0 4px 14px rgba(0,0,0,0.03)', maxWidth: '600px' },
  label: { fontSize: '13px', fontWeight: 'bold', color: '#334155', marginBottom: '5px', display: 'block' },
  inputLarge: { padding: '11px 15px', borderRadius: '10px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13.5px', backgroundColor: '#fff', width: '100%', boxSizing: 'border-box' },
  primaryBtn: { backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '12px', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13.5px' }
};
